package com.samhanair.logis.arologis.service.dispatch;
import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import com.samhanair.logis.arologis.domain.ReceivedDispatchGroup; import com.samhanair.logis.arologis.dto.dispatch.ReceivedDispatchGroupRequest; import com.samhanair.logis.arologis.repository.ReceivedDispatchGroupRepository; import java.time.LocalDate; import java.util.List; import lombok.RequiredArgsConstructor; import lombok.extern.slf4j.Slf4j; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor @Slf4j public class ReceivedDispatchGroupService {private final ReceivedDispatchGroupRepository repository;private final ObjectMapper objectMapper;@Transactional public ReceivedDispatchGroup receive(ReceivedDispatchGroupRequest r){try{String snapshot=objectMapper.writeValueAsString(r.slips());var existing=repository.findByGroupNoAndIsDeletedFalse(r.groupNo());if(existing.isPresent()){existing.get().replaceSnapshot(r.dispatchDate(),r.vehicleLabel(),r.carrierCode(),r.carrierName(),snapshot);log.info("[dispatch-group-receive] groupNo={} upsert=UPDATED",r.groupNo());return existing.get();}log.info("[dispatch-group-receive] groupNo={} upsert=CREATED",r.groupNo());return repository.save(ReceivedDispatchGroup.receive(r.groupNo(),r.dispatchDate(),r.vehicleLabel(),r.carrierCode(),r.carrierName(),snapshot));}catch(JsonProcessingException e){throw new IllegalStateException("수신 snapshot 저장 실패",e);}}@Transactional(readOnly=true) public List<ReceivedDispatchGroup> list(LocalDate d){return repository.findAllByDispatchDateAndIsDeletedFalseOrderByGroupNoAsc(d);}}
